Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='commentsonlygaps', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='A comment says only what the code cannot say', body='Write a code comment only where the code itself needs one. Write no narration of what the code does and no justification of each item. A pull request description or report gives counts and the facts a reviewer must act on.', rationale='Every comment costs tokens for each agent that later reads the file, and the diff already shows the rest.', supersedes=()))